export async function applyVenueJbSettlementOutcome(
  ctx: VenueJbSettlementContext,
): Promise<VenueJbSettlementOutcome> {
  const {
    betId,
    order,
    account,
    result,
    checked,
    platformLabel,
    loseStore,
    removeIds,
    setMessage,
  } = ctx;
  const pendingRole = order.pendingVenueRole ?? "target";
  const pendingTarget = order.pendingVenueTarget ?? order.target;
  const makeUpEligible = order.pendingVenueMakeUpEligible !== false;
  const makeUpEnabled = useUserStore().config.makeUp === true;
  const canMakeUp = makeUpEligible && makeUpEnabled;
  const pendingId = order.pendingVenueOrderId;
  // [changmen 扩展] 异步结果只归属于发起检测的队列和原单。
  const isCurrentOrder = () => loseStore.orders.get(betId) === order
    && order.pendingVenueOrderId === pendingId;
  // [A8 可证实] 受理的补单检测结束后计数；[changmen 扩展] 计数属于原单，不依赖队列存续。
  const recordTerminal = (filled: boolean) => {
    if (countedResults.has(result) || (!filled && pendingRole !== "target"))
      return;
    countedResults.add(result);
    try {
      if (ctx.markSuccess)
        ctx.markSuccess(account, pendingTarget);
      else
        markSuccessfulBet(account, betId, pendingTarget);
    }
    catch { /* 计数存储失败不改变成交事实或重新开放原补单。 */ }
  };

  const scopeCurrent = makeUpObservationScope(account);
  let legOutcome: Awaited<ReturnType<typeof resolveVenueLegOutcome>>;
  try {
    legOutcome = await resolveVenueLegOutcome(
    account,
    result,
    () => useAccountStore().updateVenueOrders(account, {
      pendingBindLinkId: order.linkId || undefined,
      pendingBindOrderId: String(result.orderId ?? "").trim() || undefined,
      waitForOrderId: String(result.orderId ?? "").trim() || undefined,
    }),
    { confirmPostAccepted: true, pmConditionId: String(checked.betId ?? "").trim() || undefined },
    );
  }
  catch {
    continueDetachedObservation(ctx, scopeCurrent);
    return "pending";
  }
  if (isMakeUpObservationRetrying(order) && !scopeCurrent())
    return "stopped";
  const venueOrders = legOutcome.orders;
  try {
    saveVenueSettlementLog({
      account,
      option: checked,
      result,
      orders: venueOrders,
      settlement: legOutcome.settlement,
      linkId: order.linkId,
    });
  }
  catch { /* 诊断异常不能改变已经确定的场馆结果。 */ }

  if (!isVenueLegRejected(legOutcome)) {
    const orderId = resolveArbBindOrderId(venueOrders, result, false);
    const bound = await bindArbLegOrder(order.linkId, account, result, venueOrders, false);
    if (!bound && orderId) {
      enqueuePendingOrderBind({
        observation: result.observation,
        target: checked.target,
        linkId: order.linkId,
        provider: result.provider,
        accountId: account.accountId,
        orderId,
        betId,
      });
    }
    const currentAtCommit = isCurrentOrder();
    try {
      if (currentAtCommit) {
        if (pendingRole !== "anchor" || !canMakeUp)
          consumeMakeUpQueue(loseStore, order, removeIds);
        else
          loseStore.clearPendingVenueOrder(betId);
      }
    }
    finally {
      recordTerminal(true);
    }
    const current = loseStore.orders.get(betId);
    if (!currentAtCommit || (current && current !== order))
      return "stopped";
    refreshOrderListAfterBind();
    if (pendingRole === "anchor") {
      if (!canMakeUp) {
        const reason = makeUpEnabled ? "补单条件未通过" : "自动补单已关闭";
        setMessage(`锚腿已成交，${reason}`);
        syncActiveBetFail(betId, `单腿已成交，${reason}`);
        void useAccountStore().refreshBalance(account);
        return "stopped";
      }
      setMessage(`锚腿已成交，开始补 ${order.target}`);
      void useAccountStore().refreshBalance(account);
      return "ready-makeup";
    }
    setMessage(`补单成功 ${platformLabel}@${checked.odds}`);
    syncActiveBetMakeupDone(betId, platformLabel, checked.odds);
    useMessageStore().loseOrderMessage(account, order, checked, false);
    // 确认成交后再刷（不在复检前刷，对齐 A8 jb）；失败不挡出队
    try {
      void useAccountStore().refreshBalance(account);
    }
    catch {
      /* 刷新失败不阻断补单出队 */
    }
    return "dequeued";
  }

  if (
    isVenueLegPendingConfirm(legOutcome) || isVenueTimeoutReject(result)
  ) {
    if (!isCurrentOrder()) {
      continueDetachedObservation(ctx, scopeCurrent);
      return "pending";
    }
    loseStore.setPendingVenueOrder(betId, String(result.orderId ?? ""), account.accountId, {
      role: pendingRole,
      observation: checked.observation,
      pendingTarget: order.pendingVenueTarget ?? order.target,
      conditionId: order.pendingVenueConditionId ?? String(checked.betId ?? ""),
      submittedAt: result.beginTime,
      pmSubmission: isPolymarketProvider(account.provider) ? pmSubmissionFromResult(result, account.accountId) : null,
      odds: checked.newOdds || checked.odds,
      betMoney: checked.betMoney,
    });
    const isPm = isPolymarketProvider(account.provider);
    // 原单迟到回执不能再被最长 30s 的队列退避拖住；仍由单飞任务控制并发。
    loseStore.deferPendingVenueOrder(betId, isPm ? 1_000 : undefined);
    if (isPm) {
      const firstAlert = !order.pendingVenueError;
      order.pendingVenueError = result.message || "PM 核验窗口结束，未取得成交或取消终态";
      loseStore.persist?.();
      if (firstAlert)
        a8Tip("PM 原单核验超时", "原单仍待确认，继续核对成交结果，禁止重复补单", 10000);
    }
    setMessage(`订单待确认，继续核对 ${String(result.orderId ?? "").slice(0, 10)}…`);
    syncActiveBetMakeupPendingConfirm(betId, result.orderId, order.pendingVenueError);
    useMessageStore().loseOrderMessage(account, order, checked, true);
    return "pending";
  }

  if (
    isVenueLegConfirmedUnfilled(legOutcome)
    && isPolymarketProvider(account.provider)
  ) {
    try {
      await persistPolymarketExecutionReject(account, result, "unfilled", {
        betOption: checked,
        linkId: order.linkId,
      });
    }
    catch {
      /* 拒单落库失败不阻断补单收尾 */
    }
  }
  const orderId = resolveArbBindOrderId(venueOrders, result, true);
  const bound = await bindArbLegOrder(order.linkId, account, result, venueOrders, true);
  if (!bound && orderId) {
    enqueuePendingOrderBind({
      observation: result.observation,
      target: checked.target,
      linkId: order.linkId,
      provider: result.provider,
      accountId: account.accountId,
      orderId,
      betId,
    });
  }
  const currentAtCommit = isCurrentOrder();
  try {
    if (currentAtCommit) {
      if (pendingRole === "anchor" || !canMakeUp)
        consumeMakeUpQueue(loseStore, order, removeIds);
      else
        loseStore.clearPendingVenueOrder(betId);
    }
  }
  finally {
    recordTerminal(false);
  }
  const current = loseStore.orders.get(betId);
  if (!currentAtCommit || (current && current !== order))
    return "stopped";
  refreshOrderListAfterBind();
  if (pendingRole === "anchor") {
    setMessage("待确认锚腿未成交，双方均未形成敞口");
    syncActiveBetFail(betId, "待确认订单未成交，补单结束");
    void useAccountStore().refreshBalance(account);
    return "stopped";
  }
  if (!canMakeUp) {
    const reason = makeUpEnabled ? "补单条件未通过" : "自动补单已关闭";
    setMessage(`待确认订单未成交，${reason}`);
    syncActiveBetFail(betId, `另一腿已成交，${reason}`);
    void useAccountStore().refreshBalance(account);
    return "stopped";
  }
  setMessage(`${order.target} 再次被拒单`);
  a8Tip("拒单提醒", `${order.target} 再次被拒单`, 3000);
  syncActiveBetMakeupRejected(betId, order.target);
  useMessageStore().loseOrderMessage(account, order, checked, true);
  // 确认未成交后补刷（资金未扣/已退）；pending 续查不加
  try {
    void useAccountStore().refreshBalance(account);
  }
  catch {
    /* 刷新失败不阻断拒单收尾 */
  }
  return "rejected";
}

/** @deprecated 用 applyVenueJbSettlementOutcome */
export const applyPmJbSettlementOutcome = applyVenueJbSettlementOutcome;

export type VenueJbResumeResult = "not-applicable" | "handled";
/** @deprecated 用 VenueJbResumeResult */
export type PmJbResumeResult = VenueJbResumeResult;

const pendingResumeFlights = new WeakSet<LoseOrder>();

export interface PendingVenueResumeParams {
  betId: number;
  order: LoseOrder;
  match?: ViewMatch;
  bet?: ViewBet;
  accountStore: ReturnType<typeof useAccountStore>;
  loseStore: ReturnType<typeof useLoseOrderStore>;
  removeIds: Set<number>;
  setMessage: (msg: string) => void;
  markSuccess: (account: PlatformAccount, target: LoseOrder["target"]) => void;
}

/** 队列项已有 pendingVenueOrderId 时续轮 settle，不再 POST */
export async function tryResumePendingVenueMakeUp(
  params: PendingVenueResumeParams,
): Promise<VenueJbResumeResult> {
  const {
    betId,
    order,
    match,
    bet,
    accountStore,
    loseStore,
    removeIds,
    setMessage,
    markSuccess,
  } = params;

  const pendingId = String(order.pendingVenueOrderId ?? "").trim();
  if (!pendingId && !order.pendingRegularReceipt)
    return "not-applicable";
  const isCurrentOrder = () => loseStore.orders.get(betId) === order
    && String(order.pendingVenueOrderId ?? "").trim() === pendingId;

  const account = accountStore.findAccount(order.pendingVenueAccountId);
  if (!account || (!order.pendingRegularReceipt && !isPendingConfirmVenueProvider(account.provider))) {
    if (!isCurrentOrder())
      return "handled";
    // [changmen 扩展] 账号消失不是原单未成交证据，保留锁并报告异常。
    order.pendingVenueError = "原单账号不可用，无法核验成交";
    loseStore.deferPendingVenueOrder(betId);
    loseStore.persist?.();
    setMessage(order.pendingVenueError);
    return "handled";
  }

  const ref = bet?.items.find(item => item.type === account.provider);
  const pendingTarget = order.pendingVenueTarget ?? order.target;
  const isPm = isPolymarketProvider(account.provider);
  let submission = validatePmSubmission(order.pendingPmSubmission, pendingId, account.accountId);
  if (isPm && !submission) {
    try {
      submission = validatePmSubmission(await getPmSubmission(account.accountId, pendingId), pendingId, account.accountId);
    }
    catch { /* 金额恢复失败不阻断原单状态核验，也不得触发新 POST。 */ }
    if (submission) {
      order.pendingPmSubmission = submission;
      order.pendingVenueBetMoney = submission.stakeUsdc;
      order.pendingVenueSubmittedAt = submission.submittedAt;
      if (isCurrentOrder())
        loseStore.persist?.();
    }
    else {
      if (!isCurrentOrder())
        return "handled";
      // 保留原单锁和队列以便恢复读取；不制造订单、不触发另一笔 POST。
      order.pendingVenueError = "原单记录读取失败，正在重试";
      loseStore.deferPendingVenueOrder(betId);
      loseStore.persist?.();
      setMessage(order.pendingVenueError);
      return "handled";
    }
  }
  // [changmen 扩展] PM 续查只能使用原单 USDC；旧队列的人民币计划额不可作为兜底。
  const sideOdds = isPm ? order.pendingVenueOdds || 0 : order.pendingVenueOdds || ref?.getOdds(pendingTarget) || order.betOdds;
  const pendingStake = isPm ? submission!.stakeUsdc : order.pendingVenueBetMoney ?? order.getBetMoney(sideOdds);
  const checked = match && bet && ref
    ? new BetOptionCtor(match, bet, ref, pendingTarget, pendingStake)
    : new BetOptionCtor(
        account.provider,
        String(order.matchId),
        order.pendingVenueConditionId ?? String(order.betId),
        "",
        pendingStake,
        pendingTarget,
        sideOdds,
      );
  checked.odds = sideOdds;
  checked.newOdds = sideOdds;
  checked.loseOrder = true;
  checked.diagnosticLinkId = order.linkId;
  checked.diagnosticAttempt = "makeup";
  checked.observation = order.pendingObservation;

  const result = Object.assign(new BetResultCtor(account.provider, true), {
    success: submission?.submitUnknown !== true,
    pmSubmitUnknown: submission?.submitUnknown,
    pmSubmittedAt: submission?.submittedAt,
    orderId: pendingId,
    pending: isPendingConfirmVenueProvider(account.provider),
    observation: order.pendingObservation,
    beginTime: submission?.submittedAt || order.pendingVenueSubmittedAt || order.createAt,
    ...(submission ? { request: { order: { side: "BUY", makerAmount: submission.makerAmount } } } : {}),
  });

  if (order.pendingRegularReceipt) {
    await processA8RegularVenueMakeUpLeg({
      betId, order, bet: { id: betId }, account, checked, result, accountStore,
      waitSec: Math.max(0, (order.pendingRegularReceipt.checkAt - Date.now()) / 1000),
      removeIds, setMessage, resumeAccepted: true,
    });
    return "handled";
  }

  await applyVenueJbSettlementOutcome({
    betId,
    order,
    account,
    result,
    checked,
    platformLabel: ref?.type ?? account.provider,
    loseStore,
    removeIds,
    setMessage,
    markSuccess,
  });

  return "handled";
}

/** 主循环只负责调度；场馆长轮询在单飞后台任务中执行，不阻塞 A8 编排循环。 */
export function schedulePendingVenueMakeUpResume(
  params: PendingVenueResumeParams,
): VenueJbResumeResult {
  // [changmen 扩展] 覆盖解除 pending 到队列出队之间的微任务间隙；新队列不继承旧任务。
  if (pendingResumeFlights.has(params.order) || isMakeUpObservationRetrying(params.order))
    return "handled";
  const orderId = String(params.order.pendingVenueOrderId ?? "").trim();
  if (!orderId && !params.order.pendingRegularReceipt)
    return "not-applicable";
  if ((Number(params.order.pendingVenueNextPollAt) || 0) > Date.now())
    return "handled";

  const isCurrentOrder = () => params.loseStore.orders.get(params.betId) === params.order;
  const workerRemoveIds = new Set<number>();
  pendingResumeFlights.add(params.order);
  void tryResumePendingVenueMakeUp({
    ...params,
    removeIds: workerRemoveIds,
  })
    .catch(() => {
      if (isCurrentOrder() && String(params.order.pendingVenueOrderId ?? "").trim() === orderId)
        params.loseStore.deferPendingVenueOrder(params.betId);
    })
    .finally(() => {
      pendingResumeFlights.delete(params.order);
    })
    .catch(() => { /* 持久化失败时内存中的出队仍有效，不能重开已成交的队列。 */ });
  return "handled";
}

/** @deprecated 用 tryResumePendingVenueMakeUp */
export const tryResumePmPendingMakeUp = tryResumePendingVenueMakeUp;

import type { ObservationContext } from "@changmen/shared/order_observation";
import type { PmSubmission } from "@changmen/shared/pm_submission";
import type { BetSide } from "@/models/match";
import type { FollowOrderInput, LoseOrderCancelledRecord, LoseOrderRecord, MakeupRuntimePhase } from "@/types/order";
import { validatePmSubmission } from "@changmen/shared/pm_submission";
import { defineStore } from "pinia";
import { LoseOrder } from "@/models/loseOrder";
import { createObservationContext, observeOrder } from "@/services/orderObservation";
import { useMatchStore } from "@/stores/matchStore";
import { useMessageStore } from "@/stores/messageStore";

const STORAGE_KEY = "LOSEORDER";
const CANCELLED_STORAGE_KEY = "LOSEORDER_CANCELLED";

/** [A8 可证实] store 定义处同步 IIFE 从 sessionStorage 恢复 */
function restoreOrdersFromSession(): Map<number, LoseOrder> {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw)
      return new Map();
    const list = JSON.parse(raw) as LoseOrderRecord[];
    const map = new Map(list.map(row => [row.betId, new LoseOrder(row)]));
    for (const order of map.values()) {
      if (order.runtimePhase === "placing" || order.runtimePhase === "settling")
        order.runtimePhase = undefined;
    }
    return map;
  }
  catch {
    return new Map();
  }
}

function restoreCancelledFromSession(): Map<number, LoseOrderCancelledRecord> {
  try {
    const raw = sessionStorage.getItem(CANCELLED_STORAGE_KEY);
    if (!raw)
      return new Map();
    const list = JSON.parse(raw) as LoseOrderCancelledRecord[];
    return new Map(list.map(row => [row.betId, row]));
  }
  catch {
    return new Map();
  }
}

/** 对齐 A8 Pinia `jb`：Map 键为 betId */
export const useLoseOrderStore = defineStore("loseorder", {
  state: () => ({
    orders: restoreOrdersFromSession(),
    cancelledOrders: restoreCancelledFromSession(),
  }),

  getters: {
    count: s => s.orders.size,
    /** linkId=0 的手动补单（订单列表上方单独展示） */
    manualOrders(state): LoseOrder[] {
      return [...state.orders.values()].filter(order => !order.isLinkBoundMakeup());
    },
    linkBoundCount(state): number {
      let n = 0;
      for (const order of state.orders.values()) {
        if (order.isLinkBoundMakeup())
          n += 1;
      }
      return n;
    },
  },

  actions: {
    restore() {
      this.orders = restoreOrdersFromSession();
      this.cancelledOrders = restoreCancelledFromSession();
    },

    ensureOrdersMap() {
      if (!(this.orders instanceof Map))
        this.orders = new Map();
      if (!(this.cancelledOrders instanceof Map))
        this.cancelledOrders = new Map();
    },

    persist() {
      sessionStorage.setItem(
        STORAGE_KEY,
        JSON.stringify([...this.orders.values()].map(o => o.toJSON())),
      );
    },

    persistCancelled() {
      sessionStorage.setItem(
        CANCELLED_STORAGE_KEY,
        JSON.stringify([...this.cancelledOrders.values()]),
      );
    },

    touchOrdersMap() {
      this.orders = new Map(this.orders);
    },

    touchCancelledMap() {
      this.cancelledOrders = new Map(this.cancelledOrders);
    },

    createOrder(order: LoseOrder) {
      const previous = this.orders.get(order.betId);
      order.observation ??= createObservationContext({}, true);
      const next = new Map(this.orders);
      next.set(order.betId, order);
      this.orders = next;
      if (previous && previous.observation?.queueId !== order.observation?.queueId)
        observeOrder(previous.observation, previous.linkId, "queue_replaced", { target: previous.target, reasonCode: "same_bet_id_overwrite" });
      observeOrder(order.observation, order.linkId, "queue_created", { target: order.target, amount: order.betMoney, odds: order.betOdds, accountId: order.accountId, source: "business_queue", phase: order.isCreateOrder ? "manual" : "automatic" });
      this.persist();
      // [A8 可证实] jb.createOrder：仅手动 isCreateOrder 时 PublishLoseOrderMessage
      if (order.isCreateOrder) {
        void useMessageStore().publishLoseOrderMessage();
      }
    },

    /** 受理后确认场馆：挂原单供 jb 续查（勿重复 POST） */
    setPendingVenueOrder(
      betId: number,
      orderId: string,
      accountId: number,
      opts: {
        role?: "target" | "anchor";
        pendingTarget?: BetSide;
        conditionId?: string;
        makeUpEligible?: boolean;
        submittedAt?: number;
        odds?: number;
        betMoney?: number;
        error?: string;
        pmSubmission?: PmSubmission | null;
        observation?: ObservationContext;
        regularReceipt?: LoseOrder["pendingRegularReceipt"];
      } = {},
    ) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const id = String(orderId ?? "").trim();
      if (!id && !opts.regularReceipt)
        return;
      const changed = String(existing.pendingVenueOrderId ?? "") !== id || existing.pendingVenueAccountId !== Number(accountId);
      if (changed) {
        existing.pendingPmSubmission = undefined;
        existing.pendingVenueReceipt = undefined;
      }
      if (opts.observation)
        existing.pendingObservation = opts.observation;
      else if (changed)
        existing.pendingObservation = undefined;
      if (!existing.pendingPmSubmission)
        existing.pendingPmSubmission = validatePmSubmission(opts.pmSubmission, id, Number(accountId)) ?? undefined;
      existing.pendingVenueOrderId = id || undefined;
      if (opts.regularReceipt)
        existing.pendingRegularReceipt = { ...opts.regularReceipt };
      else if (changed)
        existing.pendingRegularReceipt = undefined;
      existing.pendingVenueAccountId = Number(accountId) || undefined;
      existing.pendingVenueRole = opts.role ?? existing.pendingVenueRole ?? "target";
      existing.pendingVenueTarget = opts.pendingTarget ?? existing.pendingVenueTarget;
      existing.pendingVenueMakeUpEligible
        = opts.makeUpEligible ?? existing.pendingVenueMakeUpEligible ?? true;
      const conditionId = String(opts.conditionId ?? "").trim();
      if (conditionId)
        existing.pendingVenueConditionId = conditionId;
      if (changed) {
        existing.pendingVenueSubmittedAt = Number(opts.submittedAt) || Date.now();
        existing.pendingVenueOdds = opts.odds;
        existing.pendingVenueBetMoney = opts.betMoney;
        existing.pendingVenueError = undefined;
        existing.pendingVenueAttempts = 0;
        existing.pendingVenueNextPollAt = undefined;
      }
      if (opts.error)
        existing.pendingVenueError = opts.error;
      existing.runtimePhase = "venue_pending";
      this.touchOrdersMap();
      this.persist();
    },

    clearPendingVenueOrder(betId: number, persist = true) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const hadPending = Boolean(existing.pendingVenueOrderId)
        || Boolean(existing.pendingRegularReceipt)
        || Boolean((existing as { pendingPmOrderId?: string }).pendingPmOrderId);
      if (!hadPending)
        return;
      existing.pendingVenueOrderId = undefined;
      existing.pendingRegularReceipt = undefined;
      existing.pendingVenueReceipt = undefined;
      existing.pendingObservation = undefined;
      existing.pendingPmSubmission = undefined;
      existing.pendingVenueSubmittedAt = undefined;
      existing.pendingVenueOdds = undefined;
      existing.pendingVenueBetMoney = undefined;
      existing.pendingVenueError = undefined;
      existing.pendingVenueAccountId = undefined;
      existing.pendingVenueRole = undefined;
      existing.pendingVenueTarget = undefined;
      existing.pendingVenueConditionId = undefined;
      existing.pendingVenueNextPollAt = undefined;
      existing.pendingVenueAttempts = undefined;
      existing.pendingVenueMakeUpEligible = undefined;
      delete (existing as { pendingPmOrderId?: string }).pendingPmOrderId;
      delete (existing as { pendingPmAccountId?: number }).pendingPmAccountId;
      if (existing.runtimePhase === "venue_pending" || existing.runtimePhase === "pm_pending")
        existing.runtimePhase = undefined;
      this.touchOrdersMap();
      if (persist)
        this.persist();
    },

    deferPendingVenueOrder(betId: number, retryMs?: number) {
      const existing = this.orders.get(betId);
      if (!existing?.pendingVenueOrderId && !existing?.pendingRegularReceipt)
        return;
      const attempts = Math.max(0, Number(existing.pendingVenueAttempts) || 0) + 1;
      existing.pendingVenueAttempts = attempts;
      const delay = retryMs == null
        ? Math.min(30_000, 1_000 * 2 ** Math.min(attempts - 1, 5))
        : Math.max(1_000, Math.min(30_000, retryMs));
      existing.pendingVenueNextPollAt = Date.now() + delay;
      this.touchOrdersMap();
      this.persist();
    },

    setMakeupRuntimePhase(betId: number, phase: MakeupRuntimePhase | undefined) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      existing.runtimePhase = phase;
      this.touchOrdersMap();
      this.persist();
    },

    createFollowOrder(
      seed: { matchId: number; betId: number; target: BetSide; odds: number },
      follow: FollowOrderInput,
    ) {
      if (!follow?.isOpen || !follow.betMoney)
        return;
      const matchStore = useMatchStore();
      const match = matchStore.matchs.find(m => m.id === seed.matchId);
      if (!match)
        return;
      const bet = match.bets.find(b => b.id === seed.betId);
      if (!bet)
        return;
      const combinedOdds = Number(seed.odds) + Number(follow.odds ?? 0);
      const order = new LoseOrder({
        accountId: 0,
        matchId: seed.matchId,
        betId: seed.betId,
        target: seed.target,
        betMoney: Number(follow.betMoney),
        betOdds: combinedOdds,
        match: match.title,
        bet: bet.getBetName(),
        linkId: 0,
        createAt: Date.now(),
        isCreateOrder: true,
        betCount: 1,
      });
      this.createOrder(order);
    },

    /** [changmen 扩展] 清除原单锁与消费一次队列合并为一次存储写入。 */
    consumeOrder(order: LoseOrder) {
      if (this.orders.get(order.betId) !== order)
        return;
      this.clearPendingVenueOrder(order.betId, false);
      this.removeOrder(order.betId);
    },

    removeOrder(betId: number, force = false) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const next = new Map(this.orders);
      if (!force && existing.betCount > 1) {
        existing.betCount -= 1;
        next.set(betId, existing);
      }
      else {
        next.delete(betId);
        observeOrder(existing.observation, existing.linkId, "queue_removed", { target: existing.target, source: "business_queue", reasonCode: "business_remove" });
      }
      this.orders = next;
      this.persist();
    },

    /** [changmen 扩展] 侧栏补单行手动取消：出队即消失，不留占位行 */
    cancelMakeupManually(betId: number) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const linkId = Number(existing.linkId) || 0;
      this.removeOrder(betId, true);
      void import("@/stores/activeBetRunStore")
        .then(({ useActiveBetRunStore }) => useActiveBetRunStore().removeRun(betId))
        .catch(() => {});
      // 仅扩展开启时减仓；关闭时与改前「只出队」一致
      if (linkId) {
        void import("@/stores/userStore")
          .then(({ useUserStore }) => {
            if (useUserStore().extensionPrefs?.arbFailAutoSell?.enabled !== true)
              return;
            return import("@/extensions/arbBet/arbFailAutoSell").then(
              ({ maybeArbFailAutoSellByLink }) => maybeArbFailAutoSellByLink({
                linkId,
                reason: "用户取消补单",
              }),
            );
          })
          .catch(() => {});
      }
    },

    /** [A8 可证实] 60s prune：不在赛事列表的 bet 一律出队 */
    removeOrders(activeBetIds: number[]) {
      const active = new Set(activeBetIds);
      for (const betId of [...this.orders.keys()]) {
        const existing = this.orders.get(betId);
        if (!existing)
          continue;
        if (!active.has(betId) && !existing.pendingVenueOrderId && !existing.pendingRegularReceipt) {
          const linkId = Number(existing.linkId) || 0;
          this.removeOrder(betId);
          if (linkId) {
            void import("@/stores/userStore")
              .then(({ useUserStore }) => {
                if (useUserStore().extensionPrefs?.arbFailAutoSell?.enabled !== true)
                  return;
                return import("@/extensions/arbBet/arbFailAutoSell").then(
                  ({ maybeArbFailAutoSellByLink }) => maybeArbFailAutoSellByLink({
                    linkId,
                    reason: "补单目标已离盘",
                  }),
                );
              })
              .catch(() => {});
          }
        }
      }
    },

    init() {
      this.restore();
      this.ensureOrdersMap();
    },
  },
});

/** [changmen 扩展] 单笔完成即保存；consumedIds 仅防止本轮再次消费和扣减。 */
export function consumeMakeUpQueue(
  store: ReturnType<typeof useLoseOrderStore>,
  order: LoseOrder,
  consumedIds: Set<number>,
): boolean {
  if (consumedIds.has(order.betId))
    return false;
  consumedIds.add(order.betId);
  if (store.orders.get(order.betId) !== order)
    return false;
  try {
    store.consumeOrder(order);
  }
  catch { /* 存储异常不回滚已完成的内存消费，也不允许重发这一笔。 */ }
  return true;
}
import type { ObservationContext } from "@changmen/shared/order_observation";
import type { PmSubmission } from "@changmen/shared/pm_submission";
import type { BetSide } from "@/models/match";
import type { FollowOrderInput, LoseOrderCancelledRecord, LoseOrderRecord, MakeupRuntimePhase } from "@/types/order";
import { validatePmSubmission } from "@changmen/shared/pm_submission";
import { defineStore } from "pinia";
import { LoseOrder } from "@/models/loseOrder";
import { createObservationContext, observeOrder } from "@/services/orderObservation";
import { useMatchStore } from "@/stores/matchStore";
import { useMessageStore } from "@/stores/messageStore";

const STORAGE_KEY = "LOSEORDER";
const CANCELLED_STORAGE_KEY = "LOSEORDER_CANCELLED";

/** [A8 可证实] store 定义处同步 IIFE 从 sessionStorage 恢复 */
function restoreOrdersFromSession(): Map<number, LoseOrder> {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw)
      return new Map();
    const list = JSON.parse(raw) as LoseOrderRecord[];
    const map = new Map(list.map(row => [row.betId, new LoseOrder(row)]));
    for (const order of map.values()) {
      if (order.runtimePhase === "placing" || order.runtimePhase === "settling")
        order.runtimePhase = undefined;
    }
    return map;
  }
  catch {
    return new Map();
  }
}

function restoreCancelledFromSession(): Map<number, LoseOrderCancelledRecord> {
  try {
    const raw = sessionStorage.getItem(CANCELLED_STORAGE_KEY);
    if (!raw)
      return new Map();
    const list = JSON.parse(raw) as LoseOrderCancelledRecord[];
    return new Map(list.map(row => [row.betId, row]));
  }
  catch {
    return new Map();
  }
}

/** 对齐 A8 Pinia `jb`：Map 键为 betId */
export const useLoseOrderStore = defineStore("loseorder", {
  state: () => ({
    orders: restoreOrdersFromSession(),
    cancelledOrders: restoreCancelledFromSession(),
  }),

  getters: {
    count: s => s.orders.size,
    /** linkId=0 的手动补单（订单列表上方单独展示） */
    manualOrders(state): LoseOrder[] {
      return [...state.orders.values()].filter(order => !order.isLinkBoundMakeup());
    },
    linkBoundCount(state): number {
      let n = 0;
      for (const order of state.orders.values()) {
        if (order.isLinkBoundMakeup())
          n += 1;
      }
      return n;
    },
  },

  actions: {
    restore() {
      this.orders = restoreOrdersFromSession();
      this.cancelledOrders = restoreCancelledFromSession();
    },

    ensureOrdersMap() {
      if (!(this.orders instanceof Map))
        this.orders = new Map();
      if (!(this.cancelledOrders instanceof Map))
        this.cancelledOrders = new Map();
    },

    persist() {
      sessionStorage.setItem(
        STORAGE_KEY,
        JSON.stringify([...this.orders.values()].map(o => o.toJSON())),
      );
    },

    persistCancelled() {
      sessionStorage.setItem(
        CANCELLED_STORAGE_KEY,
        JSON.stringify([...this.cancelledOrders.values()]),
      );
    },

    touchOrdersMap() {
      this.orders = new Map(this.orders);
    },

    touchCancelledMap() {
      this.cancelledOrders = new Map(this.cancelledOrders);
    },

    createOrder(order: LoseOrder) {
      const previous = this.orders.get(order.betId);
      order.observation ??= createObservationContext({}, true);
      const next = new Map(this.orders);
      next.set(order.betId, order);
      this.orders = next;
      if (previous && previous.observation?.queueId !== order.observation?.queueId)
        observeOrder(previous.observation, previous.linkId, "queue_replaced", { target: previous.target, reasonCode: "same_bet_id_overwrite" });
      observeOrder(order.observation, order.linkId, "queue_created", { target: order.target, amount: order.betMoney, odds: order.betOdds, accountId: order.accountId, source: "business_queue", phase: order.isCreateOrder ? "manual" : "automatic" });
      this.persist();
      // [A8 可证实] jb.createOrder：仅手动 isCreateOrder 时 PublishLoseOrderMessage
      if (order.isCreateOrder) {
        void useMessageStore().publishLoseOrderMessage();
      }
    },

    /** 受理后确认场馆：挂原单供 jb 续查（勿重复 POST） */
    setPendingVenueOrder(
      betId: number,
      orderId: string,
      accountId: number,
      opts: {
        role?: "target" | "anchor";
        pendingTarget?: BetSide;
        conditionId?: string;
        makeUpEligible?: boolean;
        submittedAt?: number;
        odds?: number;
        betMoney?: number;
        error?: string;
        pmSubmission?: PmSubmission | null;
        observation?: ObservationContext;
        regularReceipt?: LoseOrder["pendingRegularReceipt"];
      } = {},
    ) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const id = String(orderId ?? "").trim();
      if (!id && !opts.regularReceipt)
        return;
      const changed = String(existing.pendingVenueOrderId ?? "") !== id || existing.pendingVenueAccountId !== Number(accountId);
      if (changed)
        existing.pendingPmSubmission = undefined;
      if (opts.observation)
        existing.pendingObservation = opts.observation;
      else if (changed)
        existing.pendingObservation = undefined;
      if (!existing.pendingPmSubmission)
        existing.pendingPmSubmission = validatePmSubmission(opts.pmSubmission, id, Number(accountId)) ?? undefined;
      existing.pendingVenueOrderId = id || undefined;
      if (opts.regularReceipt)
        existing.pendingRegularReceipt = { ...opts.regularReceipt };
      else if (changed)
        existing.pendingRegularReceipt = undefined;
      existing.pendingVenueAccountId = Number(accountId) || undefined;
      existing.pendingVenueRole = opts.role ?? existing.pendingVenueRole ?? "target";
      existing.pendingVenueTarget = opts.pendingTarget ?? existing.pendingVenueTarget;
      existing.pendingVenueMakeUpEligible
        = opts.makeUpEligible ?? existing.pendingVenueMakeUpEligible ?? true;
      const conditionId = String(opts.conditionId ?? "").trim();
      if (conditionId)
        existing.pendingVenueConditionId = conditionId;
      if (changed) {
        existing.pendingVenueSubmittedAt = Number(opts.submittedAt) || Date.now();
        existing.pendingVenueOdds = opts.odds;
        existing.pendingVenueBetMoney = opts.betMoney;
        existing.pendingVenueError = undefined;
        existing.pendingVenueAttempts = 0;
        existing.pendingVenueNextPollAt = undefined;
      }
      if (opts.error)
        existing.pendingVenueError = opts.error;
      existing.runtimePhase = "venue_pending";
      this.touchOrdersMap();
      this.persist();
    },

    clearPendingVenueOrder(betId: number, persist = true) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const hadPending = Boolean(existing.pendingVenueOrderId)
        || Boolean(existing.pendingRegularReceipt)
        || Boolean((existing as { pendingPmOrderId?: string }).pendingPmOrderId);
      if (!hadPending)
        return;
      existing.pendingVenueOrderId = undefined;
      existing.pendingRegularReceipt = undefined;
      existing.pendingObservation = undefined;
      existing.pendingPmSubmission = undefined;
      existing.pendingVenueSubmittedAt = undefined;
      existing.pendingVenueOdds = undefined;
      existing.pendingVenueBetMoney = undefined;
      existing.pendingVenueError = undefined;
      existing.pendingVenueAccountId = undefined;
      existing.pendingVenueRole = undefined;
      existing.pendingVenueTarget = undefined;
      existing.pendingVenueConditionId = undefined;
      existing.pendingVenueNextPollAt = undefined;
      existing.pendingVenueAttempts = undefined;
      existing.pendingVenueMakeUpEligible = undefined;
      delete (existing as { pendingPmOrderId?: string }).pendingPmOrderId;
      delete (existing as { pendingPmAccountId?: number }).pendingPmAccountId;
      if (existing.runtimePhase === "venue_pending" || existing.runtimePhase === "pm_pending")
        existing.runtimePhase = undefined;
      this.touchOrdersMap();
      if (persist)
        this.persist();
    },

    deferPendingVenueOrder(betId: number, retryMs?: number) {
      const existing = this.orders.get(betId);
      if (!existing?.pendingVenueOrderId && !existing?.pendingRegularReceipt)
        return;
      const attempts = Math.max(0, Number(existing.pendingVenueAttempts) || 0) + 1;
      existing.pendingVenueAttempts = attempts;
      const delay = retryMs == null
        ? Math.min(30_000, 1_000 * 2 ** Math.min(attempts - 1, 5))
        : Math.max(1_000, Math.min(30_000, retryMs));
      existing.pendingVenueNextPollAt = Date.now() + delay;
      this.touchOrdersMap();
      this.persist();
    },

    setMakeupRuntimePhase(betId: number, phase: MakeupRuntimePhase | undefined) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      existing.runtimePhase = phase;
      this.touchOrdersMap();
      this.persist();
    },

    createFollowOrder(
      seed: { matchId: number; betId: number; target: BetSide; odds: number },
      follow: FollowOrderInput,
    ) {
      if (!follow?.isOpen || !follow.betMoney)
        return;
      const matchStore = useMatchStore();
      const match = matchStore.matchs.find(m => m.id === seed.matchId);
      if (!match)
        return;
      const bet = match.bets.find(b => b.id === seed.betId);
      if (!bet)
        return;
      const combinedOdds = Number(seed.odds) + Number(follow.odds ?? 0);
      const order = new LoseOrder({
        accountId: 0,
        matchId: seed.matchId,
        betId: seed.betId,
        target: seed.target,
        betMoney: Number(follow.betMoney),
        betOdds: combinedOdds,
        match: match.title,
        bet: bet.getBetName(),
        linkId: 0,
        createAt: Date.now(),
        isCreateOrder: true,
        betCount: 1,
      });
      this.createOrder(order);
    },

    /** [changmen 扩展] 清除原单锁与消费一次队列合并为一次存储写入。 */
    consumeOrder(order: LoseOrder) {
      if (this.orders.get(order.betId) !== order)
        return;
      this.clearPendingVenueOrder(order.betId, false);
      this.removeOrder(order.betId);
    },

    removeOrder(betId: number, force = false) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const next = new Map(this.orders);
      if (!force && existing.betCount > 1) {
        existing.betCount -= 1;
        next.set(betId, existing);
      }
      else {
        next.delete(betId);
        observeOrder(existing.observation, existing.linkId, "queue_removed", { target: existing.target, source: "business_queue", reasonCode: "business_remove" });
      }
      this.orders = next;
      this.persist();
    },

    /** [changmen 扩展] 侧栏补单行手动取消：出队即消失，不留占位行 */
    cancelMakeupManually(betId: number) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const linkId = Number(existing.linkId) || 0;
      this.removeOrder(betId, true);
      void import("@/stores/activeBetRunStore")
        .then(({ useActiveBetRunStore }) => useActiveBetRunStore().removeRun(betId))
        .catch(() => {});
      // 仅扩展开启时减仓；关闭时与改前「只出队」一致
      if (linkId) {
        void import("@/stores/userStore")
          .then(({ useUserStore }) => {
            if (useUserStore().extensionPrefs?.arbFailAutoSell?.enabled !== true)
              return;
            return import("@/extensions/arbBet/arbFailAutoSell").then(
              ({ maybeArbFailAutoSellByLink }) => maybeArbFailAutoSellByLink({
                linkId,
                reason: "用户取消补单",
              }),
            );
          })
          .catch(() => {});
      }
    },

    /** [A8 可证实] 60s prune：不在赛事列表的 bet 一律出队 */
    removeOrders(activeBetIds: number[]) {
      const active = new Set(activeBetIds);
      for (const betId of [...this.orders.keys()]) {
        const existing = this.orders.get(betId);
        if (!existing)
          continue;
        if (!active.has(betId) && !existing.pendingVenueOrderId && !existing.pendingRegularReceipt) {
          const linkId = Number(existing.linkId) || 0;
          this.removeOrder(betId);
          if (linkId) {
            void import("@/stores/userStore")
              .then(({ useUserStore }) => {
                if (useUserStore().extensionPrefs?.arbFailAutoSell?.enabled !== true)
                  return;
                return import("@/extensions/arbBet/arbFailAutoSell").then(
                  ({ maybeArbFailAutoSellByLink }) => maybeArbFailAutoSellByLink({
                    linkId,
                    reason: "补单目标已离盘",
                  }),
                );
              })
              .catch(() => {});
          }
        }
